    {
        None,
        Freehand,      ///< 연필/지우개
        ShapeDraw,     ///< 도형 그리기 (처음 드래그, 곡선 휘기, 다각형 꼭짓점)
        ShapeMove,     ///< 편집 중인 도형 옮기기
        ShapeHandle,   ///< 편집 중인 도형 크기 핸들
