void CMyPaintDlg::OnTextStyle(UINT nID)
{
    const char style = nID == ID_TEXT_BOLD_CMD ? 'B' : nID == ID_TEXT_ITALIC_CMD ? 'I' : 'U';
    m_canvas.ToggleTextStyle(style);
    m_canvas.FocusTextEdit();
}

