        {
            const int left = x;
            add(Kind::Large, CRect(x, top, x + Px(56), bottom), IDC_TOOL_BRUSH, Popup::Brush, glyphIcon(theme::kGlyphBrush),
                _T("브러시"), _T("브러시 (아래쪽: 브러시 종류)"));
            group(_T("브러시"), left, x + Px(56));
        }
