void CFunctionGraphDlg::OnExpressionChanged()
{
    if (!m_updating)
        ScheduleUpdate(); // 목록에서 고르면 편집 칸 글자는 알림 뒤에 바뀌므로 타이머에서 읽음
}

void CFunctionGraphDlg::ScheduleUpdate()
{
    SetTimer(kPreviewTimer, kPreviewDelay, nullptr);
