function Title($hwnd) { $sb = New-Object System.Text.StringBuilder 256; [G]::GetWindowText($hwnd, $sb, 256) | Out-Null; $sb.ToString() }
function Shot($hwnd, $file) {
  Start-Sleep -Milliseconds 900
  $r = New-Object G+RECT; [G]::GetWindowRect($hwnd, [ref]$r) | Out-Null
  $bmp = New-Object System.Drawing.Bitmap ($r.R - $r.L), ($r.B - $r.T)
