  # CBN_EDITCHANGE (5)
  [G]::SendMessage($dlg, $WM_COMMAND, [IntPtr]((5 -shl 16) -bor 1140), $combo) | Out-Null
  Start-Sleep -Milliseconds 450
}

"initial info: " + (Text $info)
