  @{ e = '(x-1)^3';             info = '3차 함수: f(x) = x³ − 3x² + 3x − 1'; det = @('실근(x절편): x = 1', '극대: 없음', '극소: 없음') },
  @{ e = '2x^2+1';              info = '2차 함수: f(x) = 2x² + 1'; det = @('실근(x절편): 없음', '극소: (0, 1)', 'y절편: (0, 1)') },
  @{ e = 'x(x-2)(x+3)/4';       info = '3차 함수: f(x) = 0.25x³ + 0.25x² − 1.5x'; det = @('x = −3, x = 0, x = 2') },
  @{ e = '7';                   info = '상수 함수: f(x) = 7'; det = @('y절편: (0, 7)') },
  @{ e = '-x^2 + 4';            info = '2차 함수: f(x) = −x² + 4'; det = @('x = −2, x = 2', '극대: (0, 4)') },
