$autoY = [G]::GetDlgItem($dlg, 1150); $ymin = [G]::GetDlgItem($dlg, 1144)
Check 'auto y disables y fields' (-not [G]::IsWindowEnabled($ymin)) 'enabled'
"auto y range: " + (Text $ymin) + " ~ " + (Text ([G]::GetDlgItem($dlg, 1145)))
[G]::SendMessage($autoY, $BM_CLICK, [IntPtr]0, [IntPtr]0) | Out-Null; Start-Sleep -Milliseconds 400
