"""Claude Code 대화 기록(JSONL)을 ai_sessions/ 에 저장: 원본(raw) + 읽기 쉬운 Markdown."""
import json
import os
import re
import sys

src_dir, out_dir = sys.argv[1], sys.argv[2]
sessions = sys.argv[3:]  # "id=title" 형식

EMAIL = re.compile(r'[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}')
KEEP_EMAILS = {'noreply@anthropic.com'}
REMINDER = re.compile(r'<system-reminder>.*?</system-reminder>', re.S)


def redact(text):
    return EMAIL.sub(lambda m: m.group(0) if m.group(0) in KEEP_EMAILS else '[email redacted]', text)


def tool_summary(name, inp):
    if not isinstance(inp, dict):
        return name
    for key in ('description', 'command', 'file_path', 'pattern', 'query', 'url'):
        if key in inp and isinstance(inp[key], str):
            val = inp[key].strip().splitlines()[0] if inp[key].strip() else ''
            if key == 'description' and 'command' in inp:
                return f'{name}: {val}'
            return f'{name}: {val[:160]}'
    return name


os.makedirs(os.path.join(out_dir, 'raw'), exist_ok=True)
for spec in sessions:
    sid, title = spec.split('=', 1)
    path = os.path.join(src_dir, sid + '.jsonl')
    raw_lines = open(path, encoding='utf-8').read().splitlines()

    # 원본 (이메일만 가림)
    with open(os.path.join(out_dir, 'raw', sid + '.jsonl'), 'w', encoding='utf-8', newline='\n') as f:
        for line in raw_lines:
            f.write(redact(line) + '\n')

    md = [f'# {title}', '', f'- 세션 ID: `{sid}`', '- 도구: Claude Code (Claude 데스크톱 앱, Code 탭)',
          f'- 원본: [raw/{sid}.jsonl](raw/{sid}.jsonl)', '',
          '사용자 메시지와 AI 답변 전문, AI가 실행한 도구(파일 읽기·수정, 빌드, 테스트)는 한 줄 요약으로 적었습니다. '
          '도구 실행 결과와 AI의 내부 추론은 원본 JSONL에 있습니다.', '']
    first_time = last_time = None
    users = assistants = tools = 0
    pending_tools = []

    def flush_tools():
        global tools
        if pending_tools:
            md.append('<details><summary>도구 실행 ' + str(len(pending_tools)) + '건</summary>\n')
            for t in pending_tools:
                md.append('- ' + t.replace('\n', ' '))
            md.append('\n</details>\n')
            tools += len(pending_tools)
            pending_tools.clear()

    for line in raw_lines:
        try:
            d = json.loads(line)
        except json.JSONDecodeError:
            continue
        if d.get('isSidechain'):
            continue
        ts = d.get('timestamp')
        if ts:
            first_time = first_time or ts
            last_time = ts
        msg = d.get('message') or {}
        content = msg.get('content')
        if d.get('type') == 'user':
            texts = []
            if isinstance(content, str):
                texts = [content]
            elif isinstance(content, list):
                texts = [c.get('text', '') for c in content if c.get('type') == 'text']
            text = REMINDER.sub('', '\n'.join(texts)).strip()
            if not text or text.startswith('<command-') or text.startswith('<local-command') or text.startswith('Caveat:'):
                continue
            flush_tools()
            users += 1
            stamp = (ts or '')[:16].replace('T', ' ')
            if text.startswith('This session is being continued'):
                md += [f'## 이전 대화 요약 (자동 생성, {stamp} UTC)', '', '<details><summary>펼치기</summary>', '',
                       redact(text), '', '</details>', '']
            else:
                md += [f'## 사용자 ({stamp} UTC)', '', redact(text), '']
        elif d.get('type') == 'assistant' and isinstance(content, list):
            for c in content:
                if c.get('type') == 'text' and c.get('text', '').strip():
                    flush_tools()
                    assistants += 1
                    md += ['### AI', '', redact(c['text'].strip()), '']
                elif c.get('type') == 'tool_use':
                    pending_tools.append(redact(tool_summary(c.get('name', ''), c.get('input'))))
    flush_tools()

    header_extra = [f'- 기간: {(first_time or "")[:16].replace("T", " ")} ~ {(last_time or "")[:16].replace("T", " ")} (UTC)',
                    f'- 사용자 메시지 {users}개, AI 답변 {assistants}개, 도구 실행 {tools}건', '']
    md[4:4] = header_extra
    out = os.path.join(out_dir, f'{sid}.md')
    with open(out, 'w', encoding='utf-8', newline='\n') as f:
        f.write('\n'.join(md) + '\n')
    print(sid, users, assistants, tools, os.path.getsize(out))

